mapper.select:
SELECT opno, pno, op_date, op_time, op_type, op_price, op_amount, op_booked
FROM options
WHERE pno = #{pno}
AND op_date = TO_DATE(#{opday}, 'YYYY-MM-DD')
AND op_time = #{op_time}
ORDER BY op_type

mapper.update:
UPDATE options SET
op_booked = op_booked + #{rv_amount}
WHERE opno = #{opno}
AND (op_amount - op_booked) >= #{rv_amount}

UPDATE options SET
op_booked = op_booked - #{rv_amount}
WHERE opno = #{opno}
AND op_booked >= #{rv_amount}
